import { Pipe, PipeTransform } from '@angular/core';
import { Subscription } from 'rxjs';
import { StockService } from 'src/app/stock/stock.service';

@Pipe({
    name: 'dollar',
    standalone: true
})
export class DollarPipe implements PipeTransform {

    constructor(private stockService: StockService) {

        this.rateSub = this.stockService.exchangeRate.subscribe(res => {
            this.exchangeRate = res;
        })
    }

    rateSub: Subscription;
    exchangeRate;


    transform(value: number,
    ): string | null {
        // return formatCurrency(value, getCurrencySymbol(currencyCode, 'wide'), currencyCode);
        return new Intl.NumberFormat('en-US', {
            // style: 'currency',
            // currency: 'LBP',
            minimumFractionDigits: 0,
        }).format(Number(Math.round((value * this.exchangeRate.rate_value) / 1000) * 1000) || 0) + ` L.L`;
    }

}
